NQD = [
 dict(id='NQ24', key='TB282', tag='310 H · al-Tabari sobre 2:282', specs=['NQ-tb282'],
  title='al-Tabari, 2:282: el «extravío» de la mujer es su error por olvido; rechaza como «sin sentido» la lectura de Ibn ʿUyayna',
  ref='al-Tabari (m. 310 H), Yamiʿ al-bayan, sobre el Corán 2:282', ar_ref='تفسير الطبري، البقرة ٢٨٢', site=KSU, url='https://quran.ksu.edu.sa/tafseer/tabary/sura2-aya282.html',
  es=['Y en cuanto a lo que se ha referido de Ibn ʿUyayna, sobre la interpretación que hemos mencionado, [[a:es una interpretación errónea y sin sentido por varias razones: una, que es contraria al dicho de todos los intérpretes;]] y la segunda, que se sabe que el extravío de una de las dos mujeres en el testimonio que dio [[k:no es sino su error respecto a él por haberlo olvidado.]]'],
  prueba='Al-Tabari (m. 310 H), el exégeta más antiguo de los que cito, lee el «extravío» de 2:282 como error por olvido (nisyan) y rechaza la lectura atribuida a Ibn ʿUyayna (que «fa-tudhakkira» querría decir «la haga varón», es decir, que dos mujeres sumen un hombre sin más). Su explicación es el olvido; no dice aquí «razón» ni «naqs».',
  ojo='No lo cito para el «naqs al-ʿaql» (en este pasaje no aparece) sino para el motivo del versículo: olvido. La frase «contraria al dicho de todos los intérpretes» es afirmación suya; no lo he comprobado con otras fuentes. La lectura que rechaza (Ibn ʿUyayna, m. 198 H) también la critica al-Shawkani, que la llama «falsa» (leído en la página de Shawkani 2:282: «no hay duda de que esto es falso, no lo indica ni la ley ni la lengua ni la razón»).',
  uso=USO),
 dict(id='NQ25', key='QR282', tag='671 H · al-Qurtubi sobre 2:282 · Abu ʿUbayd', specs=['NQ-qr282'],
  title='al-Qurtubi, 2:282 (cita a Abu ʿUbayd): «tadill» = «tansa»; el extravío respecto al testimonio es olvidar una parte y recordar otra',
  ref='al-Qurtubi (m. 671 H), al-Yamiʿ li-ahkam al-Qurʾan, sobre 2:282, cuestión 36', ar_ref='تفسير القرطبي، البقرة ٢٨٢', site=KSU, url='https://quran.ksu.edu.sa/tafseer/qortobi/sura2-aya282.html',
  es=['La trigésima sexta: «que se extravíe una de ellas»: dijo Abu ʿUbayd: [[k:el sentido de «tadill» es «tansa» [olvida]; y el extravío respecto al testimonio es solo el olvido de una parte de él y el recuerdo de otra parte,]] y la persona queda perpleja entre ambas cosas, extraviada; [[a:y quien olvida el testimonio por completo no se dice que «se extravió» en él.]]'],
  prueba='Definición léxica temprana (Abu ʿUbayd al-Qasim ibn Sallam, m. 224 H, citado por al-Qurtubi): dalal en el testimonio es olvido parcial —recordar una parte, olvidar otra—, no incapacidad de entender. Es el sentido técnico que el versículo da al «extravío» de la mujer testigo.',
  ojo='Cito a Abu ʿUbayd a través de al-Qurtubi; no leí a Abu ʿUbayd. La definición se refiere a la palabra del versículo, no al hadiz ni a la «razón» en general. Por sí sola, no dice que ese olvido sea más frecuente en mujeres: eso lo añaden otros (NQ27, NQ28, NQ35).',
  uso=USO),
 dict(id='NQ26', key='MT282', tag='333 H · al-Maturidi sobre 2:282', specs=['NQ-mt282'],
  title='al-Maturidi, 2:282: las mujeres «fueron hechas» para el descuido y la «deficiencia de razón y religión» (Bujari 304), lo que genera duda en los hudud',
  ref='al-Maturidi (m. 333 H), Taʾwilat ahl al-sunna, sobre 2:282', ar_ref='تأويلات أهل السنة، البقرة ٢٨٢', site=QT, url='https://quran-tafsir.net/maturidy/sura2-aya282.html',
  es=['[[k:Y porque ellas fueron hechas [dispuestas] para el descuido, la distracción y la deficiencia de razón y de religión, según su dicho [ﷺ] [3466]: «Son deficientes en razón y religión» [al-Bujari: 304],]]',
      '[...] [[k:eso genera duda en las penas fijas [hudud], y las penas fijas son de aquello en lo que se rechaza [la pena] por duda (al-darʾ);]] por eso no se acepta [su testimonio en ellas]. Y Dios sabe más.'],
  prueba='Primer caso, en mi corpus, de uso jurídico directo del hadiz: al-Maturidi (m. 333 H), maestro de la escuela hanafi-maturidi, lo cita (con la referencia a Bujari 304) como razón de que el testimonio de mujeres no valga en los hudud: su «deficiencia» genera «duda» (shubha) y las penas fijas se evitan por la duda. Aquí «naqs al-ʿaql wa-l-din» opera como argumento procesal.',
  ojo='La frase que traduzco empieza a mitad de un razonamiento más largo: antes dice que el testimonio de dos mujeres vale «por sustitución» (badal) del de hombres y que los sustitutos no valen en los hudud; el argumento del hadiz es solo uno de ellos. «[3466]» y «[al-Bujari: 304]» son marcas del editor del texto en línea, no de al-Maturidi. El verbo «fueron hechas» (juʿilna) lo toma del hadiz y habla de disposición, no de culpa.',
  uso=USO),
 dict(id='NQ27', key='BD282', tag='c. 685 H · al-Baydawi sobre 2:282', specs=['NQ-bd282'],
  title='al-Baydawi, 2:282: la causa real es el recordatorio; y «hay en ello un indicio de la deficiencia de su razón y de la escasa precisión de ellas»',
  ref='al-Baydawi (m. c. 685 H), Anwar al-tanzil, sobre 2:282', ar_ref='تفسير البيضاوي، البقرة ٢٨٢', site=QT, url='https://quran-tafsir.net/baidawy/sura2-aya282.html',
  es=['Causa de la consideración del número: es decir, que si una de ellas se extravía respecto al testimonio, olvidándolo, la otra se lo recuerda; y la causa en realidad es el recordatorio, pero como el extravío es su motivo se le puso en su lugar, como dicen: «preparé el arma por si viene un enemigo y lo rechazo»; como si se dijera: «[es por] la voluntad de que una recuerde a la otra si se extravía». [[k:Y en ello hay un indicio de la deficiencia de su razón y de la escasa precisión de ellas.]]'],
  prueba='Al-Baydawi, uno de los comentarios más difundidos, saca del propio versículo (2:282) «un indicio» (ishʿar) de «naqs ʿaqlihinna wa-qillat dabtihinna» (deficiencia de su razón y escasa precisión). Une así el versículo y el hadiz y fija el vocabulario: «razón» + «precisión».',
  ojo='Dice «indicio», no «declaración»; y su explicación centra el «dos por uno» en el recordatorio (tadhkir), no en la incapacidad. En 4:34 (NQ31) va más lejos y generaliza. No he comprobado si toma esta fórmula de un comentario anterior (hay una tradición exegética anterior que no leí).',
  uso=USO),
 dict(id='NQ28', key='RZ282', tag='606 H · al-Razi sobre 2:282', specs=['NQ-rz282'],
  title='al-Razi, 2:282: «el olvido prevalece en la naturaleza de las mujeres, por el frío y la humedad de sus temperamentos»',
  ref='Fajr al-Din al-Razi (m. 606 H), Mafatih al-ghayb, sobre 2:282', ar_ref='مفاتيح الغيب، البقرة ٢٨٢', site=QT, url='https://quran-tafsir.net/alrazy/sura2-aya282.html',
  es=['Y el sentido es que [[k:el olvido es lo que prevalece en la naturaleza de las mujeres, por la abundancia del frío y de la humedad en sus temperamentos,]] [[a:y que la coincidencia de dos mujeres en el olvido está más lejos de la razón que la aparición del olvido en una sola mujer;]] por eso se puso a dos mujeres en lugar de un solo hombre.'],
  prueba='Explicación «humoral» de la exégesis medieval: al-Razi atribuye el olvido a la «naturaleza» de las mujeres, por el predominio de lo frío y húmedo en el temperamento, y justifica el «dos por uno» porque es menos probable que dos olviden lo mismo. Es la teoría médica de su tiempo (Galeno/Avicena) puesta al servicio de la exégesis.',
  ojo='Es una tesis de naturaleza (innata) y de medicina antigua: la teoría de los humores no se sostiene hoy (observación mía). Al-Razi ofrece su explicación sin citar el hadiz en esta frase. ʿAbduh (NQ50) cita justo esta clase de explicación («el temperamento de la mujer lo afecta el frío…») y la rechaza como «no comprobada».',
  uso=USO),
 dict(id='NQ29', key='IK282', tag='774 H · Ibn Kathir sobre 2:282', specs=['NQ-ik282'],
  title='Ibn Kathir, 2:282: «se puso a dos mujeres en lugar del hombre por la deficiencia de la razón de la mujer», y cita Muslim',
  ref='Ibn Kathir (m. 774 H), Tafsir al-Qurʾan al-ʿazim, sobre 2:282', ar_ref='تفسير ابن كثير، البقرة ٢٨٢', site=KSU, url='https://quran.ksu.edu.sa/tafseer/katheer/sura2-aya282.html',
  es=['Y esto solo se da en los bienes y en lo que se busca por el dinero; [[k:y se puso a dos mujeres en el lugar del hombre por la deficiencia de la razón de la mujer,]] como dijo Muslim en su Sahih: nos contó Qutayba: nos contó Ismaʿil ibn Yaʿfar, de ʿAmr ibn Abi ʿAmr, de al-Maqburi, de Abu Huraira, del Profeta ﷺ que dijo: «¡Oh congregación de mujeres! Dad limosna y multiplicad el pedir perdón, pues se me ha mostrado que sois la mayoría de los habitantes del Fuego.» Dijo una mujer de entre ellas, de buen juicio: «¿Y por qué nosotras, Mensajero de Dios, somos la mayoría de los habitantes del Fuego?» Dijo: «Maldecís mucho y sois desagradecidas con el cónyuge. No he visto a nadie, de entre los deficientes en razón y religión, que domine más a un hombre de juicio que vosotras.» Dijo ella: «Mensajero de Dios, ¿qué es la deficiencia de la razón y de la religión?» Dijo: «[[k:En cuanto a la deficiencia de su razón: el testimonio de dos mujeres equivale al testimonio de un hombre;]] [[a:esa es la deficiencia de la razón; y permanece noches sin rezar y rompe el ayuno en Ramadán: esa es la deficiencia de la religión.»]]'],
  prueba='Ibn Kathir (m. 774 H) une expresamente versículo y hadiz: la razón de «dos mujeres por un hombre» es «la deficiencia de la razón de la mujer», con el hadiz de Muslim como prueba. Y lo limita explícitamente a «los bienes y lo que se busca por el dinero», es decir, a los asuntos patrimoniales.',
  ojo='Aquí cita la versión de Abu Huraira en Muslim (otra rama que la de Ibn ʿUmar en Muslim 79, NQ02). Toma «ʿaql» como causa del «dos por uno»; en 4:34 (NQ32) amplía a otros asuntos. Su cita del hadiz es literal de Muslim; la lectura («deficiencia de razón» como causa) es de Ibn Kathir.',
  uso=USO),
 dict(id='NQ30', key='RZ434', tag='606 H · al-Razi sobre 4:34', specs=['NQ-rz434'],
  title='al-Razi, 4:34: «no hay duda de que las razones de los hombres y sus conocimientos son más»; superioridad «en la razón, la prudencia y la fuerza»',
  ref='Fajr al-Din al-Razi (m. 606 H), Mafatih al-ghayb, sobre 4:34', ar_ref='مفاتيح الغيب، النساء ٣٤', site=QT, url='https://quran-tafsir.net/alrazy/sura4-aya34.html',
  es=['Y sábete que la superioridad de los hombres sobre las mujeres se da por muchas razones; unas son cualidades reales y otras son normas legales. En cuanto a las cualidades reales: sábete que las virtudes reales se reducen a dos cosas: al conocimiento y a la capacidad; [[k:y no hay duda de que las razones de los hombres y sus conocimientos son más,]] y no hay duda de que su capacidad para las obras arduas es más completa; [[a:y por estas dos causas se produjo la superioridad de los hombres sobre las mujeres en la razón, la prudencia y la fuerza.]]'],
  prueba='Es la generalización más clara que leí en la exégesis medieval: al-Razi afirma que «las razones de los hombres y sus conocimientos son más» y que de ahí viene su superioridad «en la razón, la prudencia y la fuerza». No limita al testimonio, y no cita aquí el hadiz de las «naqisat»: lo afirma como cualidad «real» (no legal).',
  ojo='«No hay duda» es una aserción suya sin argumento ni dato en este pasaje; mezcla ʿaql y ʿilm (razón y conocimiento), y no dice cuánto más ni en qué ámbitos. Es el tipo de afirmación que Tahtawi (NQ51) y Qasim Amin (NQ52) combaten en el siglo XIX, atribuyendo lo que ven a la falta de educación. Contrástese con Ibn Taymiyya, que en 2:282 restringe la diferencia al dabt en testimonio (NQ49).',
  uso=USO),
 dict(id='NQ31', key='BD434', tag='c. 685 H · al-Baydawi sobre 4:34', specs=['NQ-bd434'],
  title='al-Baydawi, 4:34: «por la perfección de la razón y el buen gobierno» de los hombres; de ahí la profecía, el imamato, el testimonio…',
  ref='al-Baydawi (m. c. 685 H), Anwar al-tanzil, sobre 4:34', ar_ref='تفسير البيضاوي، النساء ٣٤', site=QT, url='https://quran-tafsir.net/baidawy/sura4-aya34.html',
  es=['…[por] la preferencia de Dios, Altísimo, de los hombres sobre las mujeres [[k:por la perfección de la razón y el buen gobierno]] y el exceso de fuerza en las obras y en los actos de obediencia; y por eso [[k:fueron distinguidos con la profecía, el imamato, la tutela (wilaya)]] y el establecimiento de los ritos, [[a:el testimonio en las asambleas de juicio, el deber del yihad y del viernes y cosas semejantes, el taʿsib y el exceso de parte en la herencia y la potestad unilateral de repudio.]]'],
  prueba='Al-Baydawi da como causa de la «qiwama» (autoridad del hombre, 4:34) la «perfección de la razón y el buen gobierno» masculinos y de ahí deriva una lista de privilegios legales: profecía, imamato, tutela, ritos, testimonio, yihad, viernes, taʿsib y herencia, repudio. Aquí la «razón» no se limita al testimonio, sino que es el fundamento de toda una lista.',
  ojo='Generaliza más que en 2:282 (NQ27). Pone «profecía» entre los privilegios masculinos: Ibn Hazm (NQ46) la discute con textos. No cita aquí hadiz; la «perfección de la razón» es afirmación suya. Datos: la fecha de muerte de al-Baydawi (685 o 691 H según las fuentes) no la verifiqué.',
  uso=USO),
 dict(id='NQ32', key='IK434', tag='774 H · Ibn Kathir sobre 4:34', specs=['NQ-ik434'],
  title='Ibn Kathir, 4:34: «el hombre es mejor que la mujer; por eso la profecía es solo de hombres, y el reino supremo (Bujari 4425) y el cargo de juez»',
  ref='Ibn Kathir (m. 774 H), Tafsir al-Qurʾan al-ʿazim, sobre 4:34', ar_ref='تفسير ابن كثير، النساء ٣٤', site=KSU, url='https://quran.ksu.edu.sa/tafseer/katheer/sura4-aya34.html',
  es=['Es decir: [[k:porque los hombres son mejores que las mujeres, y el hombre es mejor que la mujer; y por eso la profecía está reservada a los hombres]] y asimismo el reino supremo, por su dicho ﷺ: [[a:«No prosperará un pueblo que confíe su gobierno a una mujer»]] —lo recogió al-Bujari por el hadiz de ʿAbd al-Rahman ibn Abi Bakra, de su padre—; [[a:y así el cargo de juez y otros.]]'],
  prueba='Ibn Kathir deduce de 4:34 que el hombre «es mejor» (khayr) que la mujer y de ahí que la profecía, el reino supremo y el cargo de juez sean masculinos; para el reino cita Bujari 4425 (NQ13). Es la fuente más citada hoy para «la profecía solo en hombres».',
  ojo='La cadena que cita para Bujari 4425 es «ʿAbd al-Rahman ibn Abi Bakra ← su padre», otra rama que la de NQ13 (ʿAwf ← al-Hasan ← Abu Bakra): el hadiz tiene más de una vía. Su deducción («mejor») es suya: el hadiz no habla de «mejor», sino de gobierno. Ibn Hazm (NQ46) opina lo contrario respecto a la profecía.',
  uso=USO),
 dict(id='NQ33', key='AL434', tag='1270 H (1854) · al-Alusi sobre 4:34', specs=['NQ-al434'],
  title='al-Alusi (s. XIX), 4:34: «ha llegado que ellas son deficientes en razón y religión, y los hombres lo contrario»; por eso la profecía y el mensaje «según lo más conocido»',
  ref='Mahmud Shihab al-Din al-Alusi (m. 1270 H / 1854), Ruh al-maʿani, sobre 4:34', ar_ref='روح المعاني، النساء ٣٤', site=QT, url='https://quran-tafsir.net/alusy/sura4-aya34.html',
  es=['[[a:Y se dijo [que el uso indefinido «unos sobre otros»] es para dejarlo vago, para señalar que algunas mujeres son mejores que muchos hombres, y eso no es nada (no vale);]] y asimismo no precisó Él, glorificado, aquello en que consiste la preferencia, aludiendo a que no necesita detalle. [[k:Y ha llegado que ellas son deficientes en razón y religión, y los hombres lo contrario, como no se oculta,]] [[a:y por eso fueron distinguidos con el mensaje y la profecía, según lo más conocido, y con el imamato mayor y menor.]]'],
  prueba='Un exégeta del siglo XIX (al-Alusi, Bagdad, m. 1854) repite la generalización clásica: del hadiz («ha llegado que son deficientes en razón y religión») deduce que los hombres son «lo contrario» y que, por eso, la profecía y el mensaje son masculinos «según lo más conocido» («ʿala l-ashhar»). Y rechaza expresamente la lectura de que «algunas mujeres sean mejores que muchos hombres» («wa-laysa bi-shayʾ»).',
  ojo='«Wa-qad warada» («ha llegado») remite al hadiz sin darlo; la fórmula «ʿala l-ashhar» (según lo más conocido) indica que reconoce que no hay unanimidad sobre la profecía (de hecho Ibn Hazm y al-Qurtubi dicen otra cosa: NQ46–NQ47). Rechaza una lectura igualitaria con un «no es nada» sin argumentar en este pasaje.',
  uso=USO),
 dict(id='NQ34', key='SH', tag='1250 H (1834) · al-Shawkani sobre 2:282 y 4:34', specs=['NQ-sh282', 'NQ-sh434'],
  title='al-Shawkani (s. XIX): 2:282 «por la debilidad de las mujeres, a diferencia de los hombres»; 4:34: ventaja masculina en cargos, sin mencionar razón ni religión',
  ref='Muhammad ibn ʿAli al-Shawkani (m. 1250 H / 1834), Fath al-qadir, sobre 2:282 y 4:34', ar_ref='فتح القدير، البقرة ٢٨٢ والنساء ٣٤', site=QT, url='https://quran-tafsir.net/shawkany/sura2-aya282.html',
  es=['Y el sentido: si se extravía esta, la recuerda esta, y si se extravía esta, la recuerda esta, sin determinar; es decir, si se extravía una de las dos mujeres, la otra mujer se lo recuerda; [[k:y se consideró en ellas esta recordación por lo que les alcanza de la debilidad de las mujeres, a diferencia de los hombres.]]',
      'Es decir: [solo] merecieron esta ventaja por la preferencia de Dios a los hombres sobre las mujeres, por [lo cual] hay entre ellos [[k:los califas, los sultanes, los jueces, los emires y los guerreros]] [[a:y otras cosas.]]'],
  prueba='Shawkani (m. 1834), el gran jurista yemení, explica 2:282 por «la debilidad de las mujeres» (daʿf al-nisaʾ) y, en 4:34, enumera como ventaja masculina solo cargos de gobierno y guerra (califas, sultanes, jueces, emires, guerreros). Es la formulación más contenida entre los exégetas del siglo XIX que leí: sin «razón» ni «religión».',
  ojo='«Daʿf al-nisaʾ» («debilidad de las mujeres») es ambiguo: no dice si es de razón, memoria o cuerpo. Compárese NQ35: Siddiq Hasan Jan, que en lo demás sigue de cerca este texto, añade «y el exceso de razón y de religión» en 4:34 y «por la deficiencia de su razón y su precisión» en 2:282. La segunda captura (4:34) es de otra página de la misma obra (url: https://quran-tafsir.net/shawkany/sura4-aya34.html).',
  uso=USO),
 dict(id='NQ35', key='SD', tag='1307 H (1890) · Siddiq Hasan Jan sobre 2:282 y 4:34', specs=['NQ-sd282', 'NQ-sd434'],
  title='Siddiq Hasan Jan (s. XIX), Fath al-bayan: añade «por la deficiencia de su razón y su precisión» (2:282) y «y el exceso de razón y de religión» (4:34)',
  ref='Siddiq Hasan Jan al-Qannawyi (m. 1307 H / 1890), Fath al-bayan fi maqasid al-Qurʾan, sobre 2:282 y 4:34', ar_ref='فتح البيان، البقرة ٢٨٢ والنساء ٣٤', site=QT, url='https://quran-tafsir.net/seddiq/sura2-aya282.html',
  es=['Dijo Abu ʿUbayd: el sentido de «tadill» es «tansa» [olvida], [[k:es decir, por la deficiencia de su razón y su precisión;]] [[a:y el extravío respecto al testimonio es solo el olvido de una parte de él y el recuerdo de otra parte.]]',
      'Y se consideró en ellas esta recordación [[k:por lo que les alcanza de la debilidad de las mujeres, a diferencia de los hombres.]]',
      'Es decir: merecieron esta ventaja por la preferencia de Dios de ellos por encima de ellas, por [lo cual] hay entre ellos [[a:los profetas, los califas, los sultanes, los jueces, los imames y los guerreros,]] [[k:y el exceso de razón y de religión, el testimonio, el viernes y las oraciones en grupo,]] y que el hombre se casa con cuatro mujeres y a la mujer no le es lícito más que un marido, y el exceso de parte y de taʿsib en la herencia, y en su mano están el repudio, el matrimonio y el retorno, y a él se atribuye [la filiación], y otras cosas: todo esto indica la superioridad de los hombres sobre las mujeres.'],
  prueba='Siddiq Hasan Jan (India, m. 1890), representante del movimiento ahl al-hadiz, escribe en el siglo XIX un comentario que sigue de cerca al de al-Shawkani pero con adiciones propias: en 2:282, tras la definición de Abu ʿUbayd, añade «es decir, por la deficiencia de su razón y su precisión»; en 4:34, añade «el exceso de razón y de religión» a la lista de ventajas masculinas.',
  ojo='La comparación es con las páginas de al-Qurtubi (NQ25) y de al-Shawkani (NQ34), donde esas glosas no están: son de Siddiq, no de Abu ʿUbayd. Es una muestra de que en el siglo XIX la generalización se refuerza en este autor (no es la única tendencia: Tahtawi, ʿAbduh y Qasim Amin, por esos años, atribuían lo que veían al entorno y a la falta de educación: NQ50–NQ52). Pasajes tomados de la edición en línea; el número de página impreso no se muestra.',
  uso=USO),
]

NQE = [
 dict(id='NQ36', key='KH219', tag='388 H · al-Jattabi sobre Bujari 304', specs=['NQ-kh219'],
  title='al-Jattabi, A‘lam al-hadiz: el fundamento del testimonio es la razón con la honradez; «el testimonio del descuidado es débil aunque sea piadoso»',
  ref='al-Jattabi (m. 388 H), Aʿlam al-hadiz fi sharh Sahih al-Bujari, vol. 1, p. 316, «Bab tark al-ha’id al-sawm»', ar_ref='أعلام الحديث ١/٣١٦', site=SHS, url='https://shamela.ws/book/16946/219',
  es=['Y en el hadiz hay prueba de que [[k:la disminución de las obediencias es disminución de la religión;]] y hay indicación de que [[k:el fundamento del testimonio es la razón, junto con la consideración de la honradez y la veracidad,]] [[a:y que el testimonio del descuidado [mughaffal] entre la gente es débil aunque sea de agrado en la religión y la honradez.]]'],
  prueba='Al-Jattabi (m. 388 H) es el comentarista más antiguo del Bujari que leí: de este hadiz extrae dos lecciones jurídicas, (a) que dejar obras es «disminución de la religión» y (b) que lo que da valor al testimonio es la razón (capacidad de retener) además de la rectitud: el testimonio del «descuidado» es débil aunque sea piadoso. Es decir: lo que explica la regla es el descuido, no el sexo.',
  ojo='Al-Jattabi no dice aquí que todas las mujeres sean «descuidadas»: expone el principio jurídico (el testigo debe ser preciso además de recto) que él ve en el hadiz. No define «razón»; en el pasaje que leí no dice nada de la mujer en general.',
  uso=USO),
 dict(id='NQ37', key='FB892', tag='852 H · Ibn Hayar, Fath al-bari 1/406', specs=['NQ-fb892'],
  title='Ibn Hayar, Fath al-bari: «sin reproche ni censura»; «la escasa precisión indica deficiencia de razón»; rechaza leer ʿaql = diya; «proviene de la creación original»',
  ref='Ibn Hayar al-ʿAsqalani (m. 852 H), Fath al-bari, vol. 1, pp. 406–407 (ed. Salafiyya), «Bab tark al-ha’id al-sawm»', ar_ref='فتح الباري ١/٤٠٦', site=SHS, url='https://shamela.ws/book/1673/892',
  es=['Su dicho «min naqisat» es adjetivo de un sustantivo omitido. Dijo al-Tibi, sobre su dicho «no he visto a nadie deficiente…»: [[a:es un añadido a la respuesta, que se llama «istitbaʿ» [aditamiento]; así lo dijo, y hay en ello consideración.]] Y me parece que eso forma parte de los motivos de que ellas sean la mayoría de los habitantes del Fuego: pues si son causa de que se vaya la razón del hombre sensato hasta que hace o dice lo que no conviene, han compartido con él el pecado y le han añadido [más]. Su dicho «adhhab» es: más intensamente que se va; y «lubb» es más específico que «ʿaql»: es lo puro de él; y «hazim» es el que controla su asunto; y esto es una exageración en su descripción de ellas, pues si el que controla su asunto se deja llevar por ellas, quien no lo controla con más razón. Su dicho «¿y en qué consiste la deficiencia de nuestra religión?»: como si eso se les hubiera ocultado hasta que preguntaron; y la pregunta misma indica el defecto, pues aceptaron lo que se les atribuyó de las tres cosas —la abundancia [de maldiciones], la ingratitud y el hacer perder el juicio—; luego se les hizo difícil que fueran deficientes. [[k:¡Qué amable lo que les contestó ﷺ, sin reproche ni censura, sino hablándoles conforme a la medida de sus razones!]] Y con su dicho «como la mitad del testimonio del hombre» señaló su dicho Altísimo «un hombre y dos mujeres de los que os agraden como testigos»; [[k:porque el apoyo con otra [mujer] indica la escasa precisión de ella, y eso apunta a su deficiencia de razón.]] [[a:Y Ibn al-Tin refirió de algunos que tomó «ʿaql» aquí como diya, y en ello hay lejanía.]] [[a:Dije: más bien el contexto del discurso lo rechaza.]]',
      '…y que la razón admite aumento y disminución, y lo mismo la fe, como precede. [[a:Y lo que se pretende al mencionar la deficiencia en las mujeres no es reprochárselo,]] [[k:porque proviene de la creación original,]] [[a:sino la advertencia sobre ello, como precaución frente a ser fascinado por ellas.]]'],
  prueba='Ibn Hayar (m. 852 H), el comentarista más autorizado del Bujari, detalla el hadiz así: (a) «lubb» es lo puro de la razón y el «hazim» es quien controla su asunto; (b) el Profeta contestó «sin reproche ni censura»; (c) que el testigo necesite el apoyo de otra indica «escasa precisión» y esto apunta a «deficiencia de razón»; (d) rechaza leer «ʿaql» como diya (NQ10, NQ41); (e) concluye que esa deficiencia «proviene de la creación original» y no es motivo de censura, sino advertencia frente a la fascinación.',
  ojo='(1) Ibn Hayar acepta que la deficiencia es innata («aṣl al-jilqa»): va más lejos que ʿAbduh, Tahtawi y Qasim Amin (NQ50–NQ52), que la atribuyen al entorno. (2) No dice «la mitad de inteligencia»: habla de escasa precisión (qillat al-dabt). (3) Su análisis retórico (con al-Tibi) sostiene que la «deficiencia» es una segunda crítica añadida a la primera (maldecir, ingratitud), y que el pecado se vincula a lo primero. (4) Esta página es la 1/406 de la edición Salafiyya en Shamela; su paginación puede no coincidir con otras ediciones.',
  uso=USO),
 dict(id='NQ38', key='FB893', tag='852 H · Ibn Hayar, Fath al-bari 1/407 (cita a al-Nawawi)', specs=['NQ-fb893'],
  title='Ibn Hayar 1/407 (cita a al-Nawawi): el castigo se vincula a la ingratitud, «no a la deficiencia»; la «deficiencia de religión» es relativa y no implica pecado',
  ref='Ibn Hayar al-ʿAsqalani, Fath al-bari, vol. 1, p. 407 (ed. Salafiyya)', ar_ref='فتح الباري ١/٤٠٧', site=SHS, url='https://shamela.ws/book/1673/893',
  es=['Y por eso el castigo se ordenó sobre lo mencionado, la ingratitud y otras cosas, [[k:no sobre la deficiencia.]] [[a:Y la deficiencia de la religión no se limita a lo que produce pecado, sino que es más general que eso]] —lo dijo al-Nawawi—, [[a:porque es algo relativo: el perfecto, por ejemplo, es deficiente respecto al más perfecto; y de eso es la mujer menstruante: no peca por dejar la oración durante el tiempo de la menstruación, pero es deficiente respecto a la que reza.]]'],
  prueba='Ibn Hayar insiste, citando a al-Nawawi, en que el hadiz liga el castigo del Fuego a los pecados (maldición, ingratitud), «no a la deficiencia», y que la «deficiencia de religión» es un concepto relativo (nisbi): la mujer menstruante no peca, pero es «deficiente» en comparación con la que reza. Eso quita al término el sentido de falta moral.',
  ojo='Hay que leerlo junto con NQ37. Este pasaje trata de la «deficiencia de religión»; sobre la de «razón» no dice más. Que sea «relativa» no la elimina: el perfecto sigue siendo «deficiente» frente al más perfecto.',
  uso=USO),
 dict(id='NQ39', key='NW310', tag='676 H · al-Nawawi, Sharh Muslim 2/66', specs=['NQ-nw310'],
  title='al-Nawawi: «jazla» = dueña de razón y criterio; «lubb» = la perfección de la razón; «esa es la deficiencia de la razón» = «la señal de su deficiencia»',
  ref='al-Nawawi (m. 676 H), Sharh Sahih Muslim, vol. 2, p. 66, bajo «Bab bayan nuqsan al-iman bi-nuqsan al-taʿat…»', ar_ref='شرح النووي على مسلم ٢/٦٦', site=SHS, url='https://shamela.ws/book/1711/310',
  es=['Y su dicho «[[a:jazla]]» —con fatha en la ŷim y sukun en la zay—: [[a:es decir, dueña de razón y criterio;]] dijo Ibn Durayd: la jazala es la razón y la dignidad. Y en cuanto a «al-ʿashir», con fatha en la ʿayn y kasra en la shin, es en origen el que convive en general, y aquí se quiere decir el cónyuge. Y en cuanto a «al-lubb», es la razón, [[a:y se quiere decir la perfección de la razón.]] Y su dicho ﷺ «[[k:esa es la deficiencia de la razón]]» [[k:significa: la señal de su deficiencia.]]'],
  prueba='Nawawi (m. 676 H) precisa el vocabulario (lubb = perfección de la razón; ʿashir = cónyuge), señala que la mujer que interviene es «jazla» (de razón y criterio) y glosa «esa es la deficiencia de la razón» como «ʿalamat nuqsanihi» («la señal de su deficiencia»): el testimonio de dos mujeres es un signo de otra cosa, no la definición de la deficiencia.',
  ojo='Una «señal» (ʿalama) no es un «grado»: Nawawi no dice cuánto. La «cosa» de la que sería señal la dice al-Mazari en la página siguiente (NQ40: «escasa precisión»). El capítulo de Muslim bajo el que se ubica es «Exposición de la disminución de la fe por la disminución de las obediencias» (título leído en la página de Shamela).',
  uso=USO),
 dict(id='NQ40', key='NW311', tag='536 H / 676 H · al-Mazari y al-Nawawi, Sharh Muslim 2/67–68', specs=['NQ-nw311', 'NQ-nw312'],
  title='al-Mazari: la regla del testimonio es un aviso de que ellas son «escasas en precisión»; al-Nawawi: qué es la razón (discrepancia) y la «deficiencia de religión» puede ser un mandato',
  ref='al-Nawawi, Sharh Sahih Muslim, vol. 2, pp. 67–68 (cita a Abu ʿAbd Allah al-Mazari, m. 536 H)', ar_ref='شرح النووي على مسلم ٢/٦٧–٦٨', site=SHS, url='https://shamela.ws/book/1711/311',
  es=['Dijo el imam Abu ʿAbd Allah al-Mazari —Dios tenga misericordia de él—: su dicho ﷺ «en cuanto a la deficiencia de la razón: el testimonio de dos mujeres equivale al testimonio de un hombre» es una advertencia suya ﷺ sobre lo que hay detrás de ello, que es lo que Dios Altísimo advirtió en su Libro con su dicho «para que si una de ellas se extravía, la otra la recuerde»: [[k:es decir, que ellas son escasas en precisión.]] Dijo: y…',
      'Las gentes discreparon sobre qué es la razón: se dijo que es el conocimiento; se dijo que es parte de los conocimientos necesarios; se dijo que es una facultad con la que se distingue entre las realidades de lo conocido. Esto es su dicho [de al-Mazari]. Dije [al-Nawawi]: [[a:la discrepancia sobre la realidad de la razón y sus clases es muy conocida y no hace falta alargarse en ello;]] y discreparon sobre su sede: dijeron nuestros compañeros los teólogos [mutakallimun]: está en el corazón; y dijo parte de los sabios: está en la cabeza, y Dios sabe más.',
      '…[a las mujeres con] la deficiencia de la religión por dejar la oración y el ayuno en tiempo de menstruación, y puede [que esto] resulte difícil de entender, pero no es difícil sino evidente: pues la religión, la fe y el islam comparten un mismo sentido, como hemos expuesto en varios lugares; y también hemos expuesto que las obediencias se llaman fe y religión; y una vez establecido esto sabemos que quien multiplica su adoración aumenta su fe y su religión, y quien disminuye su adoración disminuye su religión. [[k:Luego, la deficiencia de la religión puede ser de un modo por el que se peca]] —como quien deja la oración o el ayuno u otras adoraciones obligatorias sin excusa—, [[a:y puede ser de un modo en que no hay pecado]] —como quien deja el viernes o la campaña militar u otro [deber] que no le es obligatorio, por una excusa—, [[a:y puede ser de un modo que es un mandato:]] como el abandono de la oración y el ayuno por la mujer menstruante.'],
  prueba='Dos de los comentaristas clásicos de Muslim: al-Mazari (m. 536 H) lee la regla del testimonio como «un aviso» (tanbih) de lo que hay detrás: que las mujeres son «escasas en precisión» (qalilat al-dabt). Y al-Nawawi (m. 676 H) añade que los sabios discrepan sobre qué es la razón (conocimiento, parte de los conocimientos necesarios, facultad) y dónde reside, y que la «deficiencia de religión» de la menstruante es de las que son un mandato y no un pecado.',
  ojo='Texto de tres capturas consecutivas (2/67, 2/68, 2/68). La primera termina con «Dijo: y…» (corte del recorte, no del texto). Al-Nawawi no resuelve qué sea «razón» ni lo aplica a las mujeres en general: lo deja abierto. El contenido concreto de al-Mazari (qalilat al-dabt) es lo más preciso que leí entre los clásicos de hadiz, y coincide con lo que dice Ibn Taymiyya (NQ49).',
  uso=USO),
 dict(id='NQ41', key='AY897', tag='855 H · al-ʿAyni, ʿUmdat al-qari 3/271', specs=['NQ-ay897'],
  title='al-ʿAyni: refiere y rechaza que «ʿaql» sea la diya («lo aparente del hadiz lo rechaza»); y recoge de al-Tibi que la «deficiencia» es un añadido retórico al reproche',
  ref='Badr al-Din al-ʿAyni (m. 855 H), ʿUmdat al-qari, vol. 3, p. 271, «Bab tark al-ha’id al-sawm»', ar_ref='عمدة القاري ٣/٢٧١', site=SHS, url='https://shamela.ws/book/5756/897',
  es=['Y Ibn al-Tin refirió de algunos que lo que se quiere decir con «ʿaql» es la diya, porque la diya de la mujer es la mitad de la del hombre. [[a:Dije: lo aparente del hadiz lo rechaza.]]',
      'Dijo al-Tibi: la respuesta es del estilo sabio, pues su dicho «no he visto…» es un añadido, ya que su dicho «maldecís mucho y sois desagradecidas con el cónyuge» es una respuesta completa; [[k:como si fuera [del modo del] aditamiento: pues la censura por la deficiencia arrastró la censura por otra cosa extraña: que el hombre perfecto y sensato se deje llevar por las mujeres deficientes.]]'],
  prueba='Al-ʿAyni (m. 855 H) repite lo que ya vimos en Ibn Hayar (NQ37): la lectura «ʿaql = diya» (porque la diya de la mujer es la mitad) existía y se rechaza; y el análisis de al-Tibi: el reproche del Profeta eran las maldiciones y la ingratitud, y la «deficiencia» es un añadido que sirve para llamar la atención sobre una cosa «extraña»: que un hombre perfecto se deje llevar por mujeres «deficientes».',
  ojo='Casi coincide con Ibn Hayar (NQ37); ambos citan a Ibn al-Tin y a al-Tibi y no sé quién depende de quién: no es una voz independiente. La lectura «diya» la presenta como «de algunos» (qawm) sin nombre. «Dije: lo aparente del hadiz lo rechaza» es de al-ʿAyni.',
  uso=USO),
]
